WITH parsed AS (SELECT id, currency, ARRAY_MIN(tier_prices) AS lowest_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices FROM price_tiers) SELECT id, currency, lowest_price, LAG(lowest_price) OVER (PARTITION BY currency ORDER BY lowest_price, id) AS prev_lowest_price, LEAD(lowest_price) OVER (PARTITION BY currency ORDER BY lowest_price, id) AS next_lowest_price, ROW_NUMBER() OVER (PARTITION BY currency ORDER BY lowest_price, id) AS event_seq FROM parsed;
